mapper.select:

where p.enterprise_id = #{enterpriseId}

    and p.supplier_id = #{querySupplierId}


    and p.status = #{status}


    and p.status != '2'


    and p.status != '2' and p.due_date is not null
    and p.due_date <= date_add(curdate(), interval #{dueWithinDays} day)


    and p.status != '2' and p.due_date is not null and p.due_date < curdate()

order by p.due_date, p.payable_id desc

mapper.update:
update t_payable
set paid_amount = #{paidAmount}, status = #{status}, update_time = sysdate()
where enterprise_id = #{enterpriseId} and payable_id = #{payableId}
